% =========================================================================
% 2D magnetotelluric (MT) resistivity model -> Tecplot PLT export script (full computational domain)
% -------------------------------------------------------------------------
% Features:
%   1. Load a test dataset in .mat format (generated by Python scipy.io.savemat; readable by MATLAB)
%   2. Export resistivity models for the sample indices specified in sample_indices
%   3. Export the full computational domain: air layers, core region, and surrounding padding (sig, zn, yn)
%      Resistivity = 1/conductivity; export LOG10(Rho) to avoid overly large legend values from 1e9
%   4. Display a MATLAB preview for each sample, with the core region outlined by a dashed white rectangle
% Output:
%   E:\Zhao\Result\Tecplot\Sample{N}_Resistivity_FullDomain.plt
%   (Tecplot ASCII format, F=POINT, I=number of horizontal nodes, J=number of vertical nodes)
% =========================================================================
clc;
clear;
close all;

%% 1. Data file and sample index settings
% =========================================================================
% Test dataset (64x32 dataset used in this project)
data_file = 'E:/Zhao/Training_dataset/Test_MT2D_64x32_Distance(50km)_Depth(10km)_Fre31_Obs25_1000.mat';

% Sample indices to export (multiple indices allowed, e.g., [891, 15, 42]; MATLAB indices start at 1)
sample_indices = 371;

% PLT output directory
save_dir = 'E:\Zhao\Result\Tecplot';
if ~exist(save_dir, 'dir')
    mkdir(save_dir);
    fprintf('Created directory: %s\n', save_dir);
end

% Load data
if ~exist(data_file, 'file')
    error('File not found, please check the path: %s', data_file);
end
fprintf('Loading data: %s ...\n', data_file);
load(data_file);          % Load sig / sig_k / zn / yn / zn0 / yn0 / obs / freq / responses
fprintf('Data loaded! sig: %s\n', mat2str(size(sig)));

% Convert coordinates to km (node coordinates: zn vertical, yn horizontal)
Y_nodes = double(yn) / 1000;
Z_nodes = double(zn) / 1000;

%% 2. Export Tecplot PLT for each sample (full computational domain)
% =========================================================================
for s = 1:length(sample_indices)
    sample_idx = sample_indices(s);
    if sample_idx < 1 || sample_idx > size(sig, 1)
        warning('Sample index %d out of range [1, %d], skipping.', sample_idx, size(sig, 1));
        continue;
    end

    % ---- Extract conductivity over the full computational domain (nz x ny, including air and padding) ----
    Sig_Model = squeeze(sig(sample_idx, :, :));
    Rho_Model = 1.0 ./ Sig_Model;      % Conductivity -> resistivity (air: 1e-9 S/m -> 1e9 Ohm.m)
    Rho_Log   = log10(Rho_Model);

    % ---- Expand cell-centered values to nodes (node count = cell count + 1; replicate edge values) ----
    RhoLog_Ext = [Rho_Log, Rho_Log(:, end)];
    RhoLog_Ext = [RhoLog_Ext; RhoLog_Ext(end, :)];

    [nz_nodes, ny_nodes] = size(RhoLog_Ext);
    if nz_nodes ~= length(Z_nodes) || ny_nodes ~= length(Y_nodes)
        error('Dimension mismatch: data %dx%d vs nodes %dx%d', ...
              nz_nodes, ny_nodes, length(Z_nodes), length(Y_nodes));
    end
    fprintf('Sample %d: full domain %d x %d cells -> %d x %d nodes\n', ...
            sample_idx, size(Sig_Model, 1), size(Sig_Model, 2), nz_nodes, ny_nodes);

    % ---- Write Tecplot PLT (export LOG10 resistivity only to avoid excessively large legend values) ----
    outfile = fullfile(save_dir, sprintf('Sample%d_Resistivity_FullDomain.plt', sample_idx));
    write_tecplot_file(outfile, Y_nodes, Z_nodes, RhoLog_Ext, ...
                       sprintf('Resistivity Model (Full Domain) - Sample %d', sample_idx));
    fprintf('PLT file generated: %s\n', outfile);

    % ---- MATLAB preview ----
    figure('Name', ['Sample ', num2str(sample_idx), ' - Full-Domain Resistivity'], ...
           'Units', 'normalized', 'Position', [0.1, 0.5, 0.6, 0.4]);
    h = pcolor(Y_nodes, Z_nodes, RhoLog_Ext);
    set(h, 'EdgeColor', 'none');
    shading flat;
    colormap(jet);
    hcb = colorbar;
    hcb.Label.String = 'Log10 Resistivity (\Omega\cdotm)';
    set(gca, 'YDir', 'reverse');       % Depth increases downward
    axis equal; axis tight;
    caxis([0, 4]);                     % Limit color range to typical subsurface values; air resistivity is 1e9
    xlabel('Distance Y (km)');
    ylabel('Depth Z (km)');
    title(['Resistivity Model (Full Domain) - Sample ', num2str(sample_idx)]);
    hold on;                            % Outline the core region (yn0/zn0)
    y_core_min = min(yn0)/1000; y_core_max = max(yn0)/1000;
    z_core_min = min(zn0)/1000; z_core_max = max(zn0)/1000;
    rectangle('Position', [y_core_min, z_core_min, y_core_max-y_core_min, z_core_max-z_core_min], ...
              'EdgeColor', 'w', 'LineWidth', 2, 'LineStyle', '--');
    text(y_core_min, z_core_max, ' Core Region', 'Color', 'w', 'VerticalAlignment', 'top');
    hold off;
end

%% Tecplot ASCII PLT writing function
% =========================================================================
function write_tecplot_file(filename, x_axis, y_axis, data_log, title_str)
    % data_log: (nz_nodes x ny_nodes) LOG10 resistivity, rows=depth (J), columns=horizontal (I)
    [nz, ny] = size(data_log);
    if length(x_axis) ~= ny || length(y_axis) ~= nz
        error('Write error: data %dx%d mismatch axes (%d x %d).', ...
              nz, ny, length(y_axis), length(x_axis));
    end
    fid = fopen(filename, 'wt');
    if fid == -1
        error('Unable to write file: %s', filename);
    end
    fprintf(fid, 'TITLE = "%s"\n', title_str);
    fprintf(fid, 'VARIABLES = "Distance (km)", "Depth (km)", "LOG10(Rho)"\n');
    % F=POINT: write (X, Y, LOG10(Rho)) point by point; I=horizontal node count, J=vertical node count
    fprintf(fid, 'ZONE T="Sample Zone", I=%d, J=%d, F=POINT\n', ny, nz);
    for i = 1:nz          % Depth direction (J, slow-varying index)
        for j = 1:ny      % Horizontal direction (I, fast-varying index)
            fprintf(fid, '%14.6f\t%14.6f\t%10.6f\n', ...
                    x_axis(j), y_axis(i), data_log(i, j));
        end
    end
    fclose(fid);
    fprintf('Tecplot file written: %s\n', filename);
end
